head.script:
scwin.checkAttr = function() {
    var attr = jQuery('#gridView1_customFilter_scrollView').attr('aria-hidden');
    return attr == "true";
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 name1 컬럼의 필터를 클릭하여 '빈값' 을 선택하여 체크해제한다.
    //In the browser, click on the filter in the name1 column and select 'empty' to uncheck it.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column11_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2list_listRow.w2grid_customFilter_list_listRow')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. '빈값' 데이터가 필터링 해제되면서 '빈값' 데이터를 제외한 나머지 데이터가 필터링되어 표시된다.
    //The 'empty' data is filtered out and the remaining data except the 'empty' data is filtered and displayed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_3_0').innerText != ''", "true");
    //Test step 2. 화면의 그리드뷰의 다른영역을 마우스로 클릭한다. 
    //Click another area of the grid view of the screen with the mouse.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column11_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify2. focusout되어지고 필터링화면이 사라진다.
    //Focused out and the filtering screen disappears.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_customFilter_scrollView').style.display == 'none'", "true");
    //Test step3. 다시 name1 컬럼의 '빈값' 을 필터로 선택한다.
    //Select 'empty' in the name1 column again as a filter.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column11_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2list_listRow.w2grid_customFilter_list_listRow')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. '빈값' 테이터를 포함한 전체 데이터가 표시된다.
    //The entire data including the 'empty' data is displayed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_3_0').innerText == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
